class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        # Iterate through all possible starting positions of a substring of length k
        for i in range(n - k + 1):
            start_char = s[i]
            # Check if the substring s[i:i+k] consists of only one distinct character
            is_uniform = True
            for j in range(i, i + k):
                if s[j] != start_char:
                    is_uniform = False
                    break

            if not is_uniform:
                continue

            # Check boundary conditions:
            # If there is a character before the substring, it must be different from start_char
            if i > 0 and s[i-1] == start_char:
                continue

            # If there is a character after the substring, it must be different from start_char
            if i + k < n and s[i+k] == start_char:
                continue

            # All conditions satisfied
            return True

        return False

