            end = nums[i + k - 1]
            # We can just mark the numbers present in this subarray
            # But since we need to know if a number appears in exactly one subarray,
            # we'll use a counter approach.

            # Instead of iterating over every element in every subarray (which is O(n*k)),
            # we can optimize by noting that for a number x to appear in a subarray starting at index j,
            # it must be within [nums[j], nums[j+k-1]].
            # However, given constraints (n <= 50), O(n*k) is perfectly fine.

            for j in range(i, i + k):
                num = nums[j]
                count_map[num] = count_map.get(num, 0) + 1

