    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # Build the graph using an adjacency list
        adj = [[] for _ in range(n)]

        for i in range(n):
            for j in range(i + 1, n):
                # Count distinct integers common to both properties[i] and properties[j]
                set_i = set(properties[i])
                set_j = set(properties[j])
                intersection_len = len(set_i & set_j)

                if intersection_len >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # Use DFS or BFS to count connected components
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                stack = [i]
                visited[i] = True
                while stack:
                    node = stack.pop()
                    for neighbor in adj[node]:
