class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        if n == 1:
            return [0, 1]

        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        self.max_len_global = 0
        self.min_nodes_global = float('inf')

        def dfs(node, parent, current_set, path_len, node_cnt):
            nonlocal self.max_len_global, self.min_nodes_global

            val = nums[node]

            if val not in current_set:
                current_set.add(val)
                # Update global for the current path ending at this node
                if path_len > self.max_len_global:
                    self.max_len_global = path_len
                    self.min_nodes_global = node_cnt
                elif path_len == self.max_len_global:
                    if node_cnt < self.min_nodes_global:
                        self.min_nodes_global = node_cnt

                # Recurse to children
                for neighbor, weight in adj[node]:
                    if neighbor != parent:
                        dfs(neighbor, node, current_set, path_len + weight, node_cnt + 1)

                # Backtrack: remove current node's value
                current_set.discard(val)
            else:
                # Duplicate value found, update global for the path ending at this node
                if path_len > self.max_len_global:
                    self.max_len_global = path_len
                    self.min_nodes_global = node_cnt
                elif path_len == self.max_len_global:
                    if node_cnt < self.min_nodes_global:
                        self.min_nodes_global = node_cnt
                # Do not add to set and do not recurse further (cannot extend through this node)

        dfs(0, -1, set(), 0, 1)
        return [self.max_len_global, self.min_nodes_global]

