class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(2, n + 1):
            fact[i] = fact[i-1] * i

        odds_avail = sorted([x for x in range(1, n+1) if x % 2 == 1])
        evens_avail = sorted([x for x in range(1, n+1) if x % 2 == 0])

        odds_left = len(odds_avail)
        evens_left = len(evens_avail)

        @lru_cache(maxsize=None)
        def count_permutations(o: int, e: int) -> int:
            if o == 0 and e == 0:
                return 1
            length = o + e
            start_odd = (o == (length + 1) // 2) and (e == length // 2)
            start_even = (o == length // 2) and (e == (length + 1) // 2)
            ways = 0
            if start_odd:
                ways += fact[o] * fact[e]
            if start_even:
                ways += fact[o] * fact[e]
            return ways

        total = count_permutations(odds_left, evens_left)
        if k > total:
            return []

        result = []
        last_parity = None  # 1 for odd, 0 for even, None for start

        while odds_left + evens_left > 0:
            # Determine candidate list
            if last_parity == 1:
                candidates = evens_avail[:]
            elif last_parity == 0:
                candidates = odds_avail[:]
            else:
                # First element: try all available in increasing order
                candidates = sorted(odds_avail + evens_avail)

            found = False
            for num in candidates:
                # Calculate new counts
                if num % 2 == 1:
                    new_o = odds_left - 1
                    new_e = evens_left
                else:
                    new_o = odds_left
                    new_e = evens_left - 1

                if k <= count_permutations(new_o, new_e):
                    result.append(num)
                    if num % 2 == 1:
                        odds_left -= 1
                    else:
                        evens_left -= 1
                    last_parity = 1 if num % 2 == 1 else 0
                    found = True
                    break

            if not found:
                return []

            # Remove the chosen number from the respective list
            if last_parity == 1:
                idx = evens_avail.index(num)
                evens_avail.pop(idx)
            elif last_parity == 0:
                idx = odds_avail.index(num)
                odds_avail.pop(idx)
            else:
                # First element: remove from whichever list it belongs to
                if num % 2 == 1:
                    idx = odds_avail.index(num)
                    odds_avail.pop(idx)
                else:
                    idx = evens_avail.index(num)
                    evens_avail.pop(idx)

        return result

